#include <bits/stdc++.h>
using namespace std;
int main() {
    string s;
    if (!(cin >> s)) return 0;
    int l = 0, r = (int)s.size() - 1;
    string t;
    while (l <= r) {
        bool left = true;
        for (int i = 0; l + i <= r - i; ++i)
            if (s[l + i] != s[r - i]) { left = s[l + i] < s[r - i]; break; }
        if (left) t += s[l++];
        else      t += s[r--];
    }
    cout << t << endl;
    return 0;
}

