#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<vector<int>> g(n, vector<int>(n)), h(n, vector<int>(n));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) cin >> g[i][j];
    int m = n / 2;
    int r0s[4] = {0, 0, m, m}, c0s[4] = {0, m, 0, m};
    bool cws[4] = {false, true, false, true};
    for (int q = 0; q < 4; ++q) {
        int r0 = r0s[q], c0 = c0s[q];
        vector<vector<int>> t(m, vector<int>(m));
        for (int i = 0; i < m; ++i)
            for (int j = 0; j < m; ++j) {
                if (cws[q]) t[j][m - 1 - i] = g[r0 + i][c0 + j];   // 顺时针：散写
                else        t[m - 1 - j][i] = g[r0 + i][c0 + j];   // 逆时针：散写
            }
        for (int i = 0; i < m; ++i)
            for (int j = 0; j < m; ++j) h[r0 + i][c0 + j] = t[i][j];
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) printf(j ? " %d" : "%d", h[i][j]);
        printf("\n");
    }
    return 0;
}

